INSERT INTO events (id, name, kind, time_mode, precision, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary) VALUES ('dawenkou', '大汶口文化', 'culture', 'circa', 'century', '约前4300–前2500；一说稍早自前4500，约前2500过渡为龙山。', -3400, 1, -40788, -4300, 1, -51588, -2500, 12, -29977, '以山东泰安大汶口命名，海岱地区新石器文化。陶鬶、拔牙习俗与陶器刻画符号，下接山东龙山文化。')
