INSERT INTO events (id, name, kind, time_mode, precision, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary) VALUES ('liangzhu', '良渚文化', 'culture', 'circa', 'century', '通行约前3300–前2300；亦记距今约5300–4000年（约前3300–前2000）。', -2800, 1, -33588, -3300, 1, -39588, -2300, 12, -27577, '环太湖地区新石器晚期文化。良渚古城、水利系统与琮璧钺玉礼器，常被视为长江下游早期国家形态。')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, kind = EXCLUDED.kind, time_mode = EXCLUDED.time_mode, precision = EXCLUDED.precision, date_note = EXCLUDED.date_note, at_year = EXCLUDED.at_year, at_month = EXCLUDED.at_month, at_abs = EXCLUDED.at_abs, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_abs = EXCLUDED.start_abs, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_abs = EXCLUDED.end_abs, summary = EXCLUDED.summary;
INSERT INTO events (id, name, kind, time_mode, precision, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary) VALUES ('majiayao', '马家窑文化', 'culture', 'circa', 'century', '约前3300–前2100。马家窑、半山、马厂为同一文化诸类型。', -2700, 1, -32388, -3300, 1, -39588, -2100, 12, -25177, '甘青地区新石器文化，仰韶西向发展的一支。以精美彩陶著称，林家等地出土早期青铜小刀。')
