INSERT INTO events (id, name, kind, time_mode, precision, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary) VALUES ('longshan', '龙山文化', 'culture', 'circa', 'century', '距今约5000–4000年；山东龙山约前2500–前2000。此取黄河中下游龙山时代总范围。', -2500, 1, -29988, -3000, 1, -35988, -2000, 12, -23977, '新石器晚期黑陶文化，分布于山东、河南、山西、陕西等地。蛋壳黑陶、夯土城址，下接二里头等早期青铜文化。')
