INSERT INTO events (id, name, kind, time_mode, precision, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary) VALUES ('taosi', '陶寺文化', 'culture', 'circa', 'century', '陶寺中期约前2100–前2000；观象台或可上溯至距今约4700年。此取龙山时代晋南陶寺通行年。', -2100, 1, -25188, -2300, 1, -27588, -1900, 12, -22777, '山西襄汾陶寺，晋南龙山时代都邑。宫殿、观象台、朱书扁壶与等级墓葬，常被用以探索早期国家与尧都传说。')
