INSERT INTO events (id, name, kind, time_mode, precision, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary) VALUES ('shimao', '石峁', 'culture', 'circa', 'century', '石峁城址属龙山晚期，通行碳十四约前2300–前1800（距今约4300–3800年）。', -2050, 1, -24588, -2300, 1, -27588, -1800, 12, -21577, '陕西神木石峁，目前所见中国史前规模最大的石构城址。皇城台、玉器与石雕，为河套—陕北早期邦国遗存。')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, kind = EXCLUDED.kind, time_mode = EXCLUDED.time_mode, precision = EXCLUDED.precision, date_note = EXCLUDED.date_note, at_year = EXCLUDED.at_year, at_month = EXCLUDED.at_month, at_abs = EXCLUDED.at_abs, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_abs = EXCLUDED.start_abs, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_abs = EXCLUDED.end_abs, summary = EXCLUDED.summary;
INSERT INTO events (id, name, kind, time_mode, precision, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary) VALUES ('erlitou', '二里头文化', 'culture', 'circa', 'century', '2015年AMS：文化早不过前1900、晚不过前1500；一期约前1750，四期约止于前1520。亦作约前1800–前1500。与文献夏朝不能简单等同。', -1640, 1, -19668, -1750, 1, -20988, -1520, 12, -18217, '河南偃师二里头，中原最早的大型都邑之一。宫城、青铜礼器与绿松石龙，是探索夏商分界与早期国家的核心遗存。')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, kind = EXCLUDED.kind, time_mode = EXCLUDED.time_mode, precision = EXCLUDED.precision, date_note = EXCLUDED.date_note, at_year = EXCLUDED.at_year, at_month = EXCLUDED.at_month, at_abs = EXCLUDED.at_abs, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_abs = EXCLUDED.start_abs, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_abs = EXCLUDED.end_abs, summary = EXCLUDED.summary;
INSERT INTO events (id, name, kind, time_mode, precision, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary) VALUES ('sanxingdui', '三星堆文化', 'culture', 'circa', 'century', '遗址约前2800–前1100。一期属宝墩文化；二三期三星堆文化约前2000–前1400；著名祭祀坑约前1200–前1000，属四期十二桥。不含宝墩一期。', -1200, 1, -14388, -2000, 1, -23988, -1100, 12, -13177, '四川广汉三星堆，古蜀青铜文明。纵目面具、神树、金杖与大型祭祀坑，与中原夏商并行而风格迥异。')
